Examples.Terraform:
# Terraform manages AWS Backup plans declaratively.
resource "aws_backup_plan" "dynamodb" {
  name = "${var.table_name}-backup-plan"

  rule {
    rule_name         = "daily-backup"
    target_vault_name = var.backup_vault_name  # default: "Default"
    schedule          = "cron(0 0 ? * * *)"   # Daily at midnight UTC

    lifecycle {
      delete_after = var.retention_days  # default: 35
    }

    start_window      = 60   # minutes
    completion_window = 180  # minutes
  }
}

resource "aws_backup_selection" "dynamodb" {
  name         = "${var.table_name}-selection"
  plan_id      = aws_backup_plan.dynamodb.id
  iam_role_arn = var.backup_service_role_arn

  resources = [
    "arn:aws:dynamodb:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:table/${var.table_name}"
  ]
}

# Alternative: tag-based selection (more scalable)
# resource "aws_backup_selection" "dynamodb_by_tag" {
#   name         = "dynamodb-tagged-tables"
#   plan_id      = aws_backup_plan.dynamodb.id
#   iam_role_arn = var.backup_service_role_arn
#
#   selection_tag {
#     type  = "STRINGEQUALS"
#     key   = "BackupPlan"
#     value = "daily"
#   }
# }
# Then tag the table: aws_dynamodb_table.example.tags = { BackupPlan = "daily" }

Examples.Cdk:
import * as backup from 'aws-cdk-lib/aws-backup';
import * as dynamodb from 'aws-cdk-lib/aws-dynamodb';
import * as cdk from 'aws-cdk-lib';

// Reference existing table
const table = dynamodb.Table.fromTableName(this, 'ExistingTable', tableName);

// Create backup plan
const plan = new backup.BackupPlan(this, 'BackupPlan', {
  backupPlanName: `${tableName}-backup-plan`,
});

// Add daily backup rule with retention
plan.addRule(new backup.BackupPlanRule({
  ruleName: 'daily-backup',
  backupVault: backup.BackupVault.fromBackupVaultName(this, 'Vault', backupVaultName ?? 'Default'),
  scheduleExpression: cdk.Schedule.cron({ hour: '0', minute: '0' }),
  deleteAfter: cdk.Duration.days(retentionDays ?? 35),
  startWindow: cdk.Duration.minutes(60),
  completionWindow: cdk.Duration.minutes(180),
}));

// Add table to backup selection by ARN
plan.addSelection('DynamoDBSelection', {
  resources: [backup.BackupResource.fromDynamoDbTable(table)],
});

// Alternative: tag-based selection (more scalable)
// plan.addSelection('TaggedResources', {
//   resources: [backup.BackupResource.fromTag('BackupPlan', 'daily')],
// });
